const lines = helpers.getLines();
let inYaml = false;
const result = lines.map((line) => {
  const trimmed = line.trim();

  if (trimmed.startsWith('```yaml')) {
    inYaml = true;
    return line;
  }

  if (inYaml && trimmed.startsWith('```')) {
    inYaml = false;
    return line;
  }

  if (!inYaml) return line;

  const colonIndex = line.indexOf(':');
  if (colonIndex === -1) return line;

  const key = line.substring(0, colonIndex).trim();
  return line.replace(/\[\[[\s\S]*?\]\]/, '[[' + '{{' + key + '}}' + ']]');
});

helpers.replaceAllText(result.join('\n'));

