const textBeforeCursor = helpers.getAllText().slice(0, cursorPos);
const cursorLine = textBeforeCursor.split('\n').length;
const result = [...lines];

let targetStart = -1;
let targetEnd = -1;
for (let i = cursorLine; i < lines.length; i++) {
  const trimmed = lines[i].trim();
  if (trimmed.startsWith('```yaml')) {
    targetStart = i;
    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim().startsWith('```')) {
        targetEnd = j;
        break;
      }
    }
    break;
  }
}

if (targetStart !== -1 && targetEnd !== -1) {
  for (let i = targetStart + 1; i < targetEnd; i++) {
    const line = lines[i];
    const colonIndex = line.indexOf(':');
    if (colonIndex !== -1) {
      const key = line.substring(0, colonIndex).trim();
      result[i] = line.replace(/\[\[[\s\S]*?\]\]/, '[[' + '{{' + key + '}}' + ']]');
    }
  }
  helpers.replaceAllText(result.join('\n'));
